 // ============================================================
 // MongoDB - NaijaCart - Portfolio 4 - NoSQL Implementation
 // ============================================================
 // Source: nosql_implementation.js
 // Matches: Postgres sample-data.sql
 //
 // Purpose:
 //  - Create MongoDB collections for NaijaCart
 //  - Insert same data as Postgres
 //  - Run verification queries
 //
 // Note:
 //  _id is auto-generated by MongoDB as ObjectId.
 //  product_id, customer_id, order_id are business keys.
 //
 // ============================================================

 // --------------------------------------------
 // 1. WAREHOUSES - Matches Postgres warehouses
 // --------------------------------------------
 // Postgres warehouses:
 //  1 = Lagos Main, Lagos
 //  2 = Abuja Hub, Abuja
 //
 db.warehouses.insertMany([
   { warehouse_id: 1, name: "Lagos Main", location: "Lagos" },
   { warehouse_id: 2, name: "Abuja Hub", location: "Abuja" }
 ]);

 // --------------------------------------------
 // 2. CUSTOMERS - Matches Postgres customers
 // --------------------------------------------
 // Postgres customers:
 //  1 = Ada Obi, ada@example.com
 //  2 = Tunde Bakare, tunde@example.com
 //
 db.customers.insertMany([
   {
     customer_id: 1,
     full_name: "Ada Obi",
     email: "ada@example.com",
     phone: "08030000001",
     city: "Lagos",
     state: "Lagos State"
   },
   {
     customer_id: 2,
     full_name: "Tunde Bakare",
     email: "tunde@example.com",
     phone: "08030000002",
     city: "Abuja",
     state: "FCT"
   }
 ]);

 // --------------------------------------------
 // 3. PRODUCTS - ISSUE 1 FIXED
 // --------------------------------------------
 // Postgres sample-data.sql:
 //  (1, 'Laptop Stand', 'Accessories', 25000, 50, 1)
 //  (2, 'Wireless Mouse', 'Accessories', 12000, 100, 1)
 //
 // NOTE:
 //  No extra fabric, No 200000 price.
 //  MongoDB now = Postgres exactly.
 //
 db.products.insertMany([
   {
     product_id: 1,
     name: "Laptop Stand",
     category: "Accessories",
     price: 25000,
     stock_quantity: 50,
     warehouse_id: 1
   },
   {
     product_id: 2,
     name: "Wireless Mouse",
     category: "Accessories",
     price: 12000,
     stock_quantity: 100,
     warehouse_id: 1
   }
 ]);

 // --------------------------------------------
 // 5. ORDERS - Matches Postgres orders
 // --------------------------------------------
 // Postgres totals:
 //  Order 1 = 25000
 //  Order 2 = 12000
 //  Order 3 = 25000
 //
 // FIXED:
 //  Order 3 warehouse_id was 2 before.
 //  Now corrected to 1 to match Postgres.
 //
 db.orders.insertMany([
   { order_id: 1, customer_id: 1, warehouse_id: 1, status: "pending", total_amount: 25000 },
   { order_id: 2, customer_id: 2, warehouse_id: 1, status: "pending", total_amount: 12000 },
   { order_id: 3, customer_id: 1, warehouse_id: 1, status: "pending", total_amount: 25000 }
 ]);

 // --------------------------------------------
 // 6. ORDER ITEMS - Matches Postgres order_items
 // --------------------------------------------
 //  Order 1 -> Laptop Stand x1 = 25000
 //  Order 2 -> Wireless Mouse x1 = 12000
 //  Order 3 -> Laptop Stand x1 = 25000
 //
 db.order_items.insertMany([
   { order_item_id: 1, order_id: 1, product_id: 1, quantity: 1, unit_price: 25000 },
   { order_item_id: 2, order_id: 2, product_id: 2, quantity: 1, unit_price: 12000 },
   { order_item_id: 3, order_id: 3, product_id: 1, quantity: 1, unit_price: 25000 }
 ]);

 // --------------------------------------------
 // 7. PAYMENTS - Matches Postgres payments
 // --------------------------------------------
 //  Payment 1 -> Order 1, 25000, Card
 //  Payment 2 -> Order 2, 12000, Transfer
 //  Payment 3 -> Order 3, 25000, Card
 //
 db.payments.insertMany([
   { payment_id: 1, order_id: 1, amount: 25000, payment_method: "Card", status: "pending" },
   { payment_id: 2, order_id: 2, amount: 12000, payment_method: "Transfer", status: "pending" },
   { payment_id: 3, order_id: 3, amount: 25000, payment_method: "Card", status: "pending" }
 ]);

 // --------------------------------------------
 // 8. INDEXES - For query optimisation
 // --------------------------------------------
 db.orders.createIndex({ warehouse_id: 1 });
 db.products.createIndex({ product_id: 1 });
 db.customers.createIndex({ customer_id: 1 });
 db.order_items.createIndex({ order_id: 1 });

 // --------------------------------------------
 // 9. VERIFICATION QUERIES
 // --------------------------------------------
 // Output in mongo_results.txt
 // MUST match inserts above
 //
 print("=== PRODUCTS ===");
 printjson(db.products.find().sort({ product_id: 1 }).toArray());

 print("=== ORDERS ===");
 printjson(db.orders.find().sort({ order_id: 1 }).toArray());

 print("=== WAREHOUSE SALES ===");
 printjson(db.orders.aggregate([
   { $group: { _id: "$warehouse_id", total_sales: { $sum: "$total_amount" } } },
   { $sort: { _id: 1 } }
 ]).toArray());

 print("=== DONE - Postgres and MongoDB now match ===");
